func (c *context) Scheme() string {
	// Can't use `r.Request.URL.Scheme`
	// See: https://groups.google.com/forum/#!topic/golang-nuts/pMUkBlQBDF0
	if c.IsTLS() {
		return "https"
	}
	if scheme := c.request.Header.Get(HeaderXForwardedProto); isHTTPOrHTTPS(scheme) {
		return scheme
	}
	if scheme := c.request.Header.Get(HeaderXForwardedProtocol); isHTTPOrHTTPS(scheme) {
		return scheme
	}
	if ssl := c.request.Header.Get(HeaderXForwardedSsl); ssl == "on" {
		return "https"
	}
	if scheme := c.request.Header.Get(HeaderXUrlScheme); isHTTPOrHTTPS(scheme) {
		return scheme
	}
	return "http"
}

// isHTTPOrHTTPS reports whether scheme is a valid HTTP scheme, i.e. `http` or `https`.
func isHTTPOrHTTPS(scheme string) bool {
	return strings.EqualFold(scheme, "http") || strings.EqualFold(scheme, "https")
}

