	patterns := []string{"/", "/a", "/a/b", "/a/:id", "/a/:id/c", "/a/*", "/:x", "/*", "/b/*", "/b/:y/z", "/ab", "/abc"}
	paths := []string{"/", "/a", "/a/", "/a/b", "/a/b/", "/a/b/c", "/a/x", "/a/x/", "/a/x/c", "/a/x/c/", "/b", "/b/", "/b/q/z", "/b/q/z/", "/ab", "/abc", "/abcd", "/x", "/x/", "/x/y", "//", "/a//b", ""}
	for _, p := range patterns {
		func() {
			defer func() {
				if r := recover(); r != nil {
					t.Errorf("PANIC registering %q: %v", p, r)
				}
			}()
			e := New()
			for _, pat := range patterns {
				pat := pat
				e.GET(pat, func(c Context) error { return c.String(200, pat) })
			}
			_ = p
			_ = e
			if p == patterns[0] {
				for _, path := range paths {
					c := e.NewContext(nil, nil)
					e.router.Find(http.MethodGet, path, c)
					h := c.Handler()
					if h == nil {
						t.Logf("path %-10q -> nil handler", path)
						continue
					}
					err := h(c)
					if err != nil {
						he := err.(*HTTPError)
						t.Logf("path %-10q -> %d %v", path, he.Code, he.Message)
					} else {
						t.Logf("path %-10q -> matched %q (ppath=%q)", path, c.response.buffer.String(), c.Path())
					}
				}
			}
		}()
	}
}
