		calls = nil
		req := httptest.NewRequest(http.MethodGet, p, nil)
		rec := httptest.NewRecorder()
		e.ServeHTTP(rec, req)
		t.Logf("%s -> code=%d body=%q calls=%v", p, rec.Code, rec.Body.String(), calls)
	}
}
